#include <bits/stdc++.h>
#define int long long
using namespace std;

void solve() {
    int n;
    cin >> n;
    vector<int> arr(3*n+1);
    for (int i = 1; i <= 3*n; i++) cin >> arr[i];
    sort(arr.begin(), arr.end());
    int ans = 0;
    vector<int> pre = arr;
    for (int i=1;i<=3*n;i++) pre[i] += pre[i-1];
    for (int i=0;i<=n;i++) {
        int st = i*2+1;
        int en = 3*n-i;
        int lo = 0, hi = n-i;
        int left = 6*(pre[3*n]-pre[en]);
        left += 3*(pre[en]-pre[st-1]);
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (mid == hi) {
                int ans1 = pre[en] - pre[en - 2*mid] - 3 * (pre[st+mid-1] - pre[st - 1]);
                ans = max(ans, left + ans1);
                break;
            }
            int mid2 = mid+1;
            int ans1 = pre[en] - pre[en - 2*mid] - 3 * (pre[st+mid-1] - pre[st - 1]);
            int ans2 = pre[en] - pre[en - 2*mid2] - 3 * (pre[st+mid2-1] - pre[st - 1]);
            if (ans1 > ans2) {
                ans = max(ans, left + ans1);
                hi = mid - 1;
            }
            else {
                ans = max(ans, left + ans2);
                lo = mid2 + 1;
            }
        }
    }
    cout << ans << '\n';
}

signed main() {
	// your code goes here
    int t;
    cin >> t;
    while (t--) {
        solve();
    }
}
